import{_ as e,o,c as t,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Memoh について","description":"","frontmatter":{},"headers":[],"relativePath":"ja/about.md","filePath":"ja/about.md","lastUpdated":1792323081000}'),l={name:"ja/about.md"};function s(h,a,i,n,d,p){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="memoh-について" tabindex="-1">Memoh について <a class="header-anchor" href="#memoh-について" aria-label="Permalink to &quot;Memoh について&quot;">​</a></h1><p>Memoh v0.13 はオープンソースのマルチエージェントプラットフォームです。1 台のマシンで複数の AI エージェントを動かし、それぞれのエージェントが自分専用のワークスペース、ブラウザ、ネットワーク、ツール、長期メモリを持ちます。</p><p>エージェントは Telegram、Discord、Slack、Feishu、WeChat、DingTalk などのチャネル、そして Memoh アプリ内で直接会話できます。コンテキストを記憶し、ブラウザやデスクトップを操作し、MCP ツールを呼び出し、スキルやコネクターをインストールし、スケジュールタスクを実行し、Bot ごとのアクセスルールを適用できます。</p><p>自分でデプロイを運用せず、マネージドな選択肢を使いたい場合は <a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> が同じプロダクトをホスティングサービスとして提供しています。</p><h2 id="提供形態" tabindex="-1">提供形態 <a class="header-anchor" href="#提供形態" aria-label="Permalink to &quot;提供形態&quot;">​</a></h2><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Desktop は Memoh Cloud またはセルフホストサーバーに接続するネイティブクライアントです。同じクライアント画面をネイティブウィンドウ・システムトレイ・ショートカット付きで包み、動かしているコンピューターを Bot が使える「コンピューター」として登録することもできます。ローカルにサーバーは立てません。</p><h3 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h3><p>Server Deploy は常時稼働・共有利用向けです。複数ユーザーで使う、自分の PC がオフラインの間もチャネルをつなぎ続ける、セルフホストサービスとして運用する——そんな場面で選びます。Docker Compose スタックにはバックエンド、ウェブクライアント、データベース、メモリサービス、ワークスペースランタイムが含まれます。</p><h2 id="v0-13-の重点" tabindex="-1">v0.13 の重点 <a class="header-anchor" href="#v0-13-の重点" aria-label="Permalink to &quot;v0.13 の重点&quot;">​</a></h2><h3 id="エージェントワークスペース" tabindex="-1">エージェントワークスペース <a class="header-anchor" href="#エージェントワークスペース" aria-label="Permalink to &quot;エージェントワークスペース&quot;">​</a></h3><p>各 Bot は隔離されたコンテナワークスペースを使えます。ファイル、コマンド実行、MCP ホスティング、ネットワークアクセス、ヘッド付きブラウザ、グラフィカルデスクトップまで揃っています。ローカル／デスクトップ構成では、ホストレベルのアクセスを意図する場合に信頼済みローカルワークスペースも選べます。</p><h3 id="クライアント" tabindex="-1">クライアント <a class="header-anchor" href="#クライアント" aria-label="Permalink to &quot;クライアント&quot;">​</a></h3><p>クライアントは日常のプロダクト面をさらに広くカバーするようになりました：Bot のセットアップ、セッション、プロバイダー、チャネル、ワークスペースのファイル、Terminal と Desktop ペイン、マーケットプレイス、Hooks、スケジュール、アクセス制御、ユーザー環境設定。v0.13 では UI 言語として英語・簡体字中国語・日本語をサポートします。</p><h3 id="hooks・スケジュール・自動化" tabindex="-1">Hooks・スケジュール・自動化 <a class="header-anchor" href="#hooks・スケジュール・自動化" aria-label="Permalink to &quot;Hooks・スケジュール・自動化&quot;">​</a></h3><p>Hooks は対応イベントの前後で小さな自動化ルールを実行し、スケジュールはチャットなしで定期的な仕事を回し続けます。マーケットプレイスのスキルとコネクターは、コードを書かずに Bot の能力を広げます。</p><h3 id="アクセス制御" tabindex="-1">アクセス制御 <a class="header-anchor" href="#アクセス制御" aria-label="Permalink to &quot;アクセス制御&quot;">​</a></h3><p>アクセス制御はチャネル側のチャット権限とワークスペース側のユーザー権限に分かれています。Bot のオーナーはチャネルメンバーを許可・ブロックし、登録ユーザーにワークスペースロールを付与し、より精密なマッチングが必要な場合は高度な ACL ルールを使えます。</p><h2 id="どこから始めるか" tabindex="-1">どこから始めるか <a class="header-anchor" href="#どこから始めるか" aria-label="Permalink to &quot;どこから始めるか&quot;">​</a></h2><ul><li><strong><a href="./guides/working-with-bots.html">Bot のセットアップ</a></strong> - Bot を作成して設定する。</li><li><strong><a href="./integrations/providers/llm.html">モデルプロバイダーとモデル</a></strong> - モデルアクセスを設定する。</li><li><strong><a href="./integrations/channels/">チャネル</a></strong> - Bot にどこから話しかけられるかを選ぶ。</li><li><strong><a href="./guides/skills.html">スキル</a></strong> と <strong><a href="./guides/supermarket.html">マーケットプレイス</a></strong> - 再利用できる能力をインストールする。</li><li><strong><a href="./guides/schedule.html">スケジュールタスク</a></strong> と <strong><a href="./guides/access.html">アクセス制御</a></strong> - 定期的な仕事と権限を運用する。</li><li><strong><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">ヘルプセンター</a></strong> - プラン・請求・アカウントの質問、チームへの連絡窓口。</li></ul>',20)])])}const c=e(l,[["render",s]]);export{u as __pageData,c as default};
